    UTF-8. A percent-encoded slash (``%2F``/``%2F``) decodes to an
    ordinary ``/`` that stays part of the identifier; routing splits on
    raw slashes only. Returns the decoded text, or ``None`` for a bad
    escape or an invalid UTF-8 encoding.
    """
    raw = bytearray()
    index = 0
    size = len(segment)
    while index < size:
        char = segment[index]
        if char == "%":
            if index + 2 >= size \
                    or segment[index + 1] not in _HEX_DIGITS \
                    or segment[index + 2] not in _HEX_DIGITS:
                return None
            raw.append(int(segment[index + 1:index + 3], 16))
            index += 3
        else:
            # ISO-8859-1 decoding means each character is one raw byte.
            raw.append(ord(char))
            index += 1
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return None


class DeviceHTTPHandler(BaseHTTPRequestHandler):
    """Routes for ``POST /v1/devices`` and ``GET /v1/devices/{device_id}``."""

    service: DeviceService  # injected via :func:`handler_for`

    def _send_data_file_unavailable(self) -> None:
        """Answer 503/field=data_file after a durable write was rolled back."""
        self._send_json(503, {
            "message": "state file is temporarily unavailable; the change "
                       "was not applied",
            "field": "data_file"})

    # -- routing ----------------------------------------------------------

    def do_POST(self) -> None:
        try:
            self._route_POST()
        except PersistenceUnavailable:
            self._send_data_file_unavailable()

    def _route_POST(self) -> None:
        path = urlsplit(self.path).path
        if path == _DEVICES_PATH:
            self._handle_register()
        elif path == _DEVICES_VERIFIED_PATH:
            self._handle_register_verified()
        elif path == _PREKEYS_PATH + "/claim-batch":
            self._handle_claim_prekey_batch()
        elif path == _PREKEYS_PATH + "/claim":
            self._handle_claim_prekey()
        elif path == _SESSIONS_FROM_BATCH_CLAIM_PATH:
            self._handle_create_sessions_from_batch_claim()
        elif path == _SESSIONS_FROM_CLAIM_PATH:
            self._handle_create_session_from_claim()
        elif path == _SESSIONS_PATH:
            self._handle_create_session()
        elif path.startswith(_SESSIONS_PATH + "/") \
                and path.endswith("/rotate"):
            self._route_rotate_session(path)
        elif path.startswith(_SESSIONS_PATH + "/") \
                and path.endswith("/sync/checkpoint"):
            self._route_session_sync_checkpoint(path)
        elif path.startswith(_SESSIONS_PATH + "/") \
                and path.endswith("/sync/ack"):
            self._route_session_sync_ack(path)
        elif path == _MESSAGES_PATH:
            self._handle_post_message()
        elif path == _MESSAGES_SUBMIT_PATH:
            self._handle_submit_message()
        elif path == _MESSAGES_SUBMIT_VERIFIED_PATH:
            self._handle_submit_verified_message()
        elif path == _MESSAGES_SUBMIT_VERIFIED_BATCH_PATH:
            self._handle_submit_verified_message_batch()
        elif path == _INBOX_JOBS_PATH:
            self._handle_inbox_job()
        elif path == _EVENT_GC_BATCH_CLEANUP_PATH:
            self._handle_event_gc_cleanup_expired_batch()
        elif path == _EVENT_GC_BATCH_CHECKPOINT_PATH:
            self._handle_event_gc_batch_checkpoint()
        elif path == _EVENT_GC_BATCH_CONSUME_PATH:
            self._handle_event_gc_batch_consume()
        elif path == _EVENT_GC_BATCH_LEASE_EVENTS_CONSUME_PATH:
            self._handle_event_gc_batch_lease_event_consume()
        elif path == _LEASE_SUBS_PATH:
            self._handle_lease_subscription_register()
        elif path.startswith(_LEASE_SUBS_PATH + "/"):
            self._route_lease_subscription_ack(path)
        elif path == _EVENT_GC_BATCH_CLAIM_PATH:
            self._handle_event_gc_batch_claim()
        elif path == _EVENT_GC_BATCH_LEASE_RENEW_PATH:
            self._handle_event_gc_batch_lease_renew()
        elif path == _EVENT_GC_BATCH_LEASE_PATH:
            self._handle_event_gc_batch_lease_op()
        elif path.startswith(_EVENT_GC_PATH + "/"):
            self._route_event_gc(path)
        elif path == _INBOX_JOBS_PATH + "/recover-batch":
            self._handle_inbox_job_recover_batch()
        elif path == _INBOX_JOBS_PATH + "/dispatch-batch":
            self._handle_inbox_job_dispatch_batch()
        elif path == _INBOX_JOBS_PATH + "/cancel-batch":
            self._handle_inbox_job_cancel_batch()
        elif path == _INBOX_JOBS_PATH + "/complete-batch":
            self._handle_inbox_job_complete_batch()
        elif path == _INBOX_JOBS_PATH + "/ack-batch":
            self._handle_inbox_job_ack_batch()
        elif path == _INBOX_JOBS_PATH + "/renew-batch":
            self._handle_inbox_job_renew_batch()
        elif path == _INBOX_JOBS_PATH + "/release-batch":
            self._handle_inbox_job_release_batch()
        elif path == _INBOX_JOBS_PATH + "/lease-status-batch":
            self._handle_inbox_job_lease_status_batch()
        elif path == _INBOX_JOBS_PATH + "/status-batch":
            self._handle_inbox_job_status_batch()
        elif path == _GROUPS_PATH:
            self._handle_create_group()
        elif path == _GROUP_SESSIONS_PATH:
            self._handle_create_group_session()
        elif path.startswith(_GROUP_SESSIONS_PATH + "/") \
                and path.endswith("/sync/checkpoint"):
            self._route_group_sync_checkpoint(path)
        elif path.startswith(_GROUP_SESSIONS_PATH + "/") \
                and path.endswith("/rotate"):
            self._route_rotate_group_session(path)
        elif path.startswith(_GROUPS_PATH + "/"):
            self._route_group_member(path)
        elif path.startswith(_DEVICES_PATH + "/") and path.endswith("/revoke"):
            self._route_revoke(path)
        elif path.startswith(_DEVICES_PATH + "/") \
                and path.endswith("/revoke-verified"):
            self._route_revoke_verified(path)
        elif path.startswith(_DEVICES_PATH + "/") \
                and path.endswith("/identity-verifications"):
            self._route_identity_verifications(path)

        body = self.service.get_session(session_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

